      expect(screen.getByRole('button', { name: '更新到 v0.2.0' }) !== null).toBe(true),
    );

    // 用户触发更新失败 → error 态转「重试更新」
    checkMock.mockRejectedValue(new Error('network: 更新检查失败'));
