    // 结果事件不另起消息：本轮恰一条 assistant（turn-12），结果就地补全该消息
    expect(result.current.messages.filter((message) => message.id === 'turn-12')).toHaveLength(1);
    expect(bashToolParts(result.current.messages)).toHaveLength(1);
  });
});

