    const messages = fold([message(1, [{ kind: 'text', text: '只有回答' }])]);

    render(<AgentMessages messages={messages} loading={false} running={false} />);

    expect(stickyNodes()).toHaveLength(0);
    expect(bubblesOfRole('assistant')).toHaveLength(1);
  });

