        status,
      );
      expect(contentHeight(), status).toBe(expectedHeight(['user', 'assistant', 'assistant']));
      const sticky = stickyNodes()[0] as HTMLElement;
      expect(Number.parseFloat(sticky.style.height), status).toBe(contentHeight() - PADDING);
      unmount();
    }
