          },
          parts: [],
        },
      ];
      const { unmount } = render(
        <AgentMessages messages={messages} loading={false} running={false} />,
      );
      expect(screen.queryByTestId('turn-status-line')).toBeNull();
      expect(screen.queryAllByTestId('chat-bubble')).toHaveLength(0);
      unmount();
    }
  });
});

