      .getAllByTestId(/^nav-/)
      .map((nav) => nav.getAttribute('data-testid'));
    expect(navOrder).toEqual([
      'nav-info',
      'nav-changes',
      'nav-explores',
      'nav-architecture',
      'nav-config',
