  it('退避节奏（fake timers）：首败后恰 1s / 2s / 4s 逐拍自动补发，任一退避点前零提前触发（自动补发至多 3 次）', async () => {
    vi.useFakeTimers();
    const roundCalls = scriptDetailRounds([
      okRound(fakeDetail([])),
