    await flushTimers(1);
    expect(roundCalls()).toBe(4);

    // 退避 4s：恰 4s 补发（3999ms 处静默）——自动补发累计 3 次
    await flushTimers(3999);
    expect(roundCalls()).toBe(4);
    await flushTimers(1);
