    expect(roundCalls()).toBe(3);
    expect(result.current.refreshFailed).toContain('手动轮失败');

    // 手动轮失败 +1s：退避序列重置后按 1s 补发（未取消的旧重试若残留将在此
    // 双发——计数恰 4 即取消语义与零交错的复合证据）
    await flushTimers(1000);
