    // 新通知轮经 300ms 去抖发起（call 3）
    expect(roundCalls()).toBe(3);
    expect(result.current.refreshFailed).toContain('新通知轮失败');

    // 旧重试点（首败 +1s = t+1300）过境 → 零补发（旧重试已作废；若残留将在此
