    expect(roundCalls()).toBe(3);
    expect(invokeMock).toHaveBeenLastCalledWith('get_change_detail', {
      root: '/repo',
      id: 'change-b',
    });

    // 原退避时间窗（远超 1s）推进 → 零补发（零遗留计时器、零交错查询）
    await flushTimers(10_000);
    expect(roundCalls()).toBe(3);
  });

  it('卸载后推进时间 → 零自动补发（零遗留计时器）', async () => {
    vi.useFakeTimers();
