    expect(screen.queryByTestId('change-chat-disabled-reason')).toBeNull();
    expect(screen.getByTestId('change-chat-composer').textContent).not.toContain('undefined');
  });

  it('running 与 disabled 正交：两态停止入口均在（禁用只禁输入与发送，不隐去运行中停止面）', async () => {
    ipc.list = () => Promise.resolve({ sessions: [historyItem('ses-1')], total: 1 });
    ipc.detail = summary([turn(11, 'running', 'ses-1')], 'ses-1');
    const rendered = await mountPanel();
    await expandHistory();
    await selectHistoryItem(0);
    await waitFor(() => expect(screen.getByTestId('change-chat-stop')).toBeTruthy());
    expect(screen.queryByTestId('change-chat-disabled-reason')).toBeNull();

    await rerenderPanel(rendered, { runActive: true });

    expect(screen.getByTestId('change-chat-stop') !== null, '运行中停止面不被整面板禁用隐去').toBe(
      true,
    );
    expect(screen.getByTestId('change-chat-disabled-reason').textContent).toBe('流程运行中');
    expect(sendButton().disabled).toBe(true);
  });

  it('点击停止 → agent_stop 携 { root, sessionId }（停止面不携执行根）', async () => {
    ipc.list = () => Promise.resolve({ sessions: [historyItem('ses-1')], total: 1 });
    ipc.detail = summary([turn(11, 'running', 'ses-1')], 'ses-1');
    await mountPanel();
    await expandHistory();
    await selectHistoryItem(0);
    await waitFor(() => expect(screen.getByTestId('change-chat-stop')).toBeTruthy());

    fireEvent.click(screen.getByTestId('change-chat-stop'));
    await act(async () => {});

    expect(callsOf('agent_stop')).toHaveLength(1);
    expect(argsOf('agent_stop')).toEqual({ root: ROOT, sessionId: 'ses-1' });
    expect(Object.keys(argsOf('agent_stop')).sort()).toEqual(['root', 'sessionId']);
  });
});

// ---------------------------------------------------------------------------
// 文案逐字（骨架抽取的回归证据 R-5）：骨架接管渲染后文案逐字不变
// ---------------------------------------------------------------------------

describe('ChangeChatPanel：骨架文案逐字回归', () => {
  it('标题 / 状态行 / 空占位 / 加载更多 / 错误前缀 / 窄条展开 title 六处逐字', async () => {
    await mountPanel();
    expect(screen.getByTestId('change-chat-actions').textContent).toContain('通用 Agent');
    expect(screen.getByTestId('change-chat-note').textContent).toBe('发送首条消息即开启新会话');
    expect(screen.getByTestId('change-chat-new').getAttribute('aria-label')).toBe('新会话');
    expect(screen.getByTestId('change-chat-history').getAttribute('aria-label')).toBe('历史会话');

    await expandHistory();
    expect(screen.getByTestId('change-chat-history-empty').textContent).toBe('（暂无历史会话）');
  });

  it('清单错误文案前缀逐字（「加载历史会话失败：」+ 理由）与「加载更多」按钮文案', async () => {
    ipc.list = () => Promise.reject(new Error('库不可读'));
    const failed = await mountPanel();
    await expandHistory();
    expect(screen.getByTestId('change-chat-history-error').textContent).toBe(
      '加载历史会话失败：Error: 库不可读',
    );
    failed.unmount();

    ipc.list = () => Promise.resolve({ sessions: [historyItem('ses-1')], total: 3 });
    await mountPanel();
    await expandHistory();
    expect(screen.getByTestId('change-chat-history-more').textContent).toBe('加载更多');
  });

  it('折叠窄条：竖向标题「通用 Agent」+ 展开入口 title「展开通用 Agent」+ 箭头图标', () => {
    render(panelUi());

    expect(screen.getByTestId('change-chat-rail').textContent).toContain('通用 Agent');
    const expand = screen.getByTestId('change-chat-expand');
    expect(expand.getAttribute('title')).toBe('展开通用 Agent');
    expect(expand.querySelector('svg'), '箭头为图标（无字面字符）').not.toBeNull();
  });
});

