  it('排布回归：常驻行插于标题头行与 detail 行之间（D10——头行 / 常驻行 / detail 依次相邻）', () => {
    renderNode(settledWorkerNode({ detail: '评估通过：verdict pass' }));
    const node = screen.getByTestId('run-step-node');
