describe('ChangeFlowGraph：边渲染与重渲染', () => {
  it('label 为 null 的常规边与带 label 的回跳边混存 → 均正常渲染不抛错', async () => {
    const base = detail({
      pipeline: REQUIREMENT_PHASES.map((phase) =>
        phase === 'dev-design'
          ? {
              phase,
              attempts: [
                attempt({
                  startAt: '2026-09-03T00:00:00Z',
                  backtrackTo: 'proposal',
                  backtrackReason: '设计未对齐提案',
                }),
              ],
            }
          : { phase, attempts: [] },
      ),
    });
    const nodes: RuntimeFlowNode[] = [
      runNode({
        id: 'run:dev-design:1:executor:0',
        phase: 'dev-design',
        colIndex: REQUIREMENT_PHASES.indexOf('dev-design'),
        parentId: 'col:dev-design',
        status: 'passed',
      }),
      runNode({
        id: 'run:dev-design:1:verdictGate:0',
        phase: 'dev-design',
        colIndex: REQUIREMENT_PHASES.indexOf('dev-design'),
        parentId: 'col:dev-design',
        runStepKind: 'verdictGate',
        group: 'gate',
        role: null,
        sessionId: null,
      }),
    ];
    const edges: UnifiedRunEdge[] = [
      {
        fromNodeKey: 'dev-design:1:executor:0',
        toNodeKey: 'dev-design:1:verdict_gate:0',
        edgeKind: 'forward',
        runId: 'run-1727',
      },
      {
        fromNodeKey: 'dev-design:1:executor:0',
        toNodeKey: 'dev-design:1:verdict_gate:0',
        edgeKind: 'backtrack',
        runId: 'run-1727',
      },
    ];
    const graph = buildFlowGraph(base, nodes, edges);
    expect(graph.edges.map((edge) => edge.kind)).toEqual(['forward', 'backtrack']);
    renderGraph(graph, materialsFor(base));

    // 重放节点度量后，handleBounds 就位、边随真实渲染树输出
    await measureNodes();
    await waitFor(() =>
      expect(document.querySelectorAll('.react-flow__edge')).toHaveLength(graph.edges.length),
    );
    // 回跳边标签改经 HTML overlay 的标记点承载（SVG text 面退役——长 reason 不再
    // 撑成单行）；标记点全量文本随 aria-label 可读
    await waitFor(() => expect(screen.getAllByTestId('edge-label-marker')).toHaveLength(1));
    expect(screen.getByTestId('edge-label-marker').getAttribute('aria-label')).toBe(
      '边标签：设计未对齐提案',
    );
    expect(document.querySelectorAll('.react-flow__edge-text')).toHaveLength(0);
    // 边样式按 kind 分流：回跳边 warn 虚线、前进边 border 实线
    const paths = [...document.querySelectorAll<SVGPathElement>('.react-flow__edge-path')];
    expect(paths).toHaveLength(2);
    const warnPaths = paths.filter((path) =>
      (path.getAttribute('style') ?? '').includes('var(--warn)'),
    );
    expect(warnPaths).toHaveLength(1);
    expect(warnPaths[0]?.getAttribute('style')).toContain('6 4');
  });

  it('判别只看 label：无 label 的边不挂标记点，带 label 的边挂且悬停出全文', async () => {
    const reason = `实现缺陷回改：${'未覆盖边界条件'.repeat(40)}`;
    const base = detail({
      pipeline: REQUIREMENT_PHASES.map((phase) =>
        phase === 'implement'
          ? { phase, attempts: [attempt({ backtrackTo: 'test-design', backtrackReason: reason })] }
          : { phase, attempts: [] },
      ),
    });
    const nodes: RuntimeFlowNode[] = [
      runNode({ id: 'run:implement:1:executor:0', status: 'passed' }),
      runNode({
        id: 'run:implement:1:verdictGate:0',
        runStepKind: 'verdictGate',
        group: 'gate',
        order: 1,
        role: null,
        sessionId: null,
        status: 'passed',
      }),
    ];
    const edges: UnifiedRunEdge[] = [
      {
        fromNodeKey: 'implement:1:executor:0',
        toNodeKey: 'implement:1:verdict_gate:0',
        edgeKind: 'forward',
        runId: 'run-1727',
      },
      {
        fromNodeKey: 'implement:1:verdict_gate:0',
        toNodeKey: 'implement:1:executor:0',
        edgeKind: 'backtrack',
        runId: 'run-1727',
      },
    ];
    renderGraph(buildFlowGraph(base, nodes, edges), materialsFor(base));
    await measureNodes();
    await waitFor(() =>
      expect(document.querySelectorAll('.react-flow__edge')).toHaveLength(edges.length),
    );

    // 两条边仅一条带 label → 恰一个标记点（label 有无即判据，与 kind 无关）；
    // 全量记因随 aria-label 可读（弹层开合属 HoverCard 库语义，不在此逐个断言）
    await waitFor(() => expect(screen.getAllByTestId('edge-label-marker')).toHaveLength(1));
    const marker = screen.getByTestId('edge-label-marker');
    expect(marker.getAttribute('aria-label')).toBe(`边标签：${reason}`);
    expect(document.querySelectorAll('.react-flow__edge-text')).toHaveLength(0);
  });

  it('边界：空 graph（columns / nodes / edges 为空）→ 渲染空画布不抛错', () => {
    const materials: FlowMaterials = { columnDocs: {} };
    expect(() => renderGraph({ columns: [], nodes: [], edges: [] }, materials)).not.toThrow();
    expect(screen.getByTestId('flow-graph') !== null).toBe(true);
    expect(screen.queryByTestId('flow-column')).toBeNull();
    expect(screen.queryByTestId('run-step-node')).toBeNull();
  });

  it('等价图重渲染（刷新取数全引用新建）→ 边不卸载重挂：节点声明布局尺寸，内部 handle 度量跨重建保留', async () => {
    const before = detail();
    const { rerender } = renderGraph(
      buildFlowGraph(
        before,
        [runNode({ status: 'passed', endedAt: 1_727_000_005_000 }), gateNode()],
        SELF_EDGES,
      ),
      materialsFor(before),
    );
    await measureNodes();
    await waitFor(() => expect(document.querySelectorAll('.react-flow__edge')).toHaveLength(1));
    const firstEdge = document.querySelector('.react-flow__edge');

    // 刷新轮：detail / 节点 / 边 / 挂载素材全为新建引用，内容逐字段等价
    const after = detail();
    rerender(
      <ChangeFlowGraph
        graph={buildFlowGraph(
          after,
          [runNode({ status: 'passed', endedAt: 1_727_000_005_000 }), gateNode()],
          SELF_EDGES,
        )}
        materials={materialsFor(after)}
        onSelect={() => {}}
      />,
    );

    // 未再测量即成立：边 DOM 未卸载重挂（重测窗口内零闪烁）
    expect(document.querySelectorAll('.react-flow__edge')).toHaveLength(1);
    expect(document.querySelector('.react-flow__edge')).toBe(firstEdge);
  });

  it('边界：graph 变化重渲染 → 新节点集合渲染、旧节点零残留', async () => {
    const before = detail();
    const { rerender } = renderGraph(buildFlowGraph(before, [runNode()]), materialsFor(before));
    await waitFor(() => expect(screen.getAllByTestId('run-step-node')).toHaveLength(1));

    const after = detail();
    const secondGraph = buildFlowGraph(after, [
      runNode({
        id: 'run:test-design:1:evaluator:0',
        phase: 'test-design',
        colIndex: REQUIREMENT_PHASES.indexOf('test-design'),
        parentId: 'col:test-design',
        runStepKind: 'evaluator',
        role: 'evaluator',
      }),
      runNode({
        id: 'run:test-design:1:decision:0',
        phase: 'test-design',
        colIndex: REQUIREMENT_PHASES.indexOf('test-design'),
        parentId: 'col:test-design',
        runStepKind: 'decision',
        role: 'decision',
      }),
    ]);
    rerender(
      <ChangeFlowGraph graph={secondGraph} materials={materialsFor(after)} onSelect={() => {}} />,
    );

    await waitFor(() => expect(screen.getAllByTestId('run-step-node')).toHaveLength(2));
    expect(screen.getByTestId('rf__node-run:test-design:1:evaluator:0') !== null).toBe(true);
    expect(screen.queryByTestId('rf__node-run:implement:1:executor:0')).toBeNull();
    expect(screen.getAllByTestId('flow-column')).toHaveLength(REQUIREMENT_PHASES.length);
  });
});

