import { useChat } from '@ai-sdk/react';
import type { Channel } from '@tauri-apps/api/core';
import { act, renderHook, waitFor } from '@testing-library/react';
import type { ChatTransport } from 'ai';
import { afterEach, beforeEach, describe, expect, expectTypeOf, it, vi } from 'vite-plus/test';

import type { AgentEvent, AgentRunMessage, TurnSummary } from '../types/dto';
import { type commands } from '../types/generated/bindings';
import { eventToChunk, type AgentUIMessage, type AgentUIMessageChunk } from './agent-adapter';
import { TauriAgentTransport } from './agent-transport';
import { ipc } from './ipc';
import { driftCount, driftReports, resetDrift } from './ipc-drift';

// ---------------------------------------------------------------------------
// 进程边界 Mock：invoke 按命令名分发（agent_start 可切换 resolve/reject 并记录
// 入参）；Channel mock 与真实 `@tauri-apps/api/core` 的 `Channel` **同构**——
// 原型 accessor + 私有字段，投递经私有字段（`core.js` 的 `_Channel_deliver` 直读
// 私有字段、不读 `this.onmessage`）：替身若把 `onmessage` 放成实例字段，投递路径
// 与生产不一致，装配层的拦截面也就测不到。ReadableStream 与 chunk 消费用真实
// 实现。
// ---------------------------------------------------------------------------

const { ChannelMock, invokeMock } = vi.hoisted(() => {
  class ChannelMock {
    #onmessage: (message: unknown) => void = () => {};
    public id = 1;
    public static instances: ChannelMock[] = [];
    constructor() {
      ChannelMock.instances.push(this);
    }
    public get onmessage(): (message: unknown) => void {
      return this.#onmessage;
    }
    public set onmessage(handler: (message: unknown) => void) {
      this.#onmessage = handler;
    }
    /** Rust → 前端投递（与真实 `Channel` 的 deliver 同构：读私有字段） */
    public deliver(message: unknown): void {
      this.#onmessage(message);
    }
  }
  return { ChannelMock, invokeMock: vi.fn() };
});

vi.mock('@tauri-apps/api/core', () => ({ invoke: invokeMock, Channel: ChannelMock }));

// ---------------------------------------------------------------------------
// fixture
// ---------------------------------------------------------------------------

const ROOT = 'C:\\demo\\alpha';
/** 多数用例只见一轮：分组键与消息 id 锚点都由它派生（`turn-<turnId>`） */
const TURN = 13;

function runStarted(seq: number, turnId: number | null = TURN): AgentEvent {
  return {
    seq,
    turnId,
    timestampMs: 1727000000000,
    kind: 'runStarted',
    model: 'claude-opus',
    sessionId: 's-1',
    tools: ['Bash'],
    mcpServers: [],
  };
}

function textEvent(seq: number, text: string, turnId: number | null = TURN): AgentEvent {
  return {
    seq,
    turnId,
    timestampMs: 1727000000000,
    kind: 'message',
    role: 'assistant',
    blocks: [{ kind: 'text', text }],
    parentToolUseId: null,
  };
}

/** 零块密封 assistant 事件（「无部件的事件」形态） */
function emptyBlocksEvent(seq: number, turnId: number | null = TURN): AgentEvent {
  return {
    seq,
    turnId,
    timestampMs: 1727000000000,
    kind: 'message',
    role: 'assistant',
    blocks: [],
    parentToolUseId: null,
  };
}

/** 密封 user 提问事件（transport 侧恒零 chunk） */
function userMessage(seq: number, text: string, turnId: number | null = TURN): AgentEvent {
  return {
    seq,
    turnId,
    timestampMs: 1727000000000,
    kind: 'message',
    role: 'user',
    blocks: [{ kind: 'text', text }],
    parentToolUseId: null,
  };
}

/** system 通知事件（aux 四变体之一） */
function systemNotice(seq: number, turnId: number | null = TURN): AgentEvent {
  return {
    seq,
    turnId,
    timestampMs: 1727000000000,
    kind: 'systemNotice',
    subtype: 'permission_denial',
    payload: { tool: 'Bash' },
  };
}

/** 轮收敛事件（aux 四变体之一；仍产 `data-run-result`） */
function turnDone(seq: number, turnId: number | null = TURN): AgentEvent {
  return {
    seq,
    turnId,
    timestampMs: 1727000000000,
    kind: 'turnDone',
    subtype: 'success',
    isError: false,
    numTurns: 2,
    durationMs: 900,
    costUsd: 0.1,
    usage: { input_tokens: 5 },
    sessionId: 's-1',
  };
}

/** 未识别事件透传（aux 四变体之一） */
function raw(seq: number, turnId: number | null = TURN): AgentEvent {
  return {
    seq,
    turnId,
    timestampMs: 1727000000000,
    kind: 'raw',
    eventType: 'mystery',
    rawJson: '{"type":"mystery"}',
  };
}

function textDelta(seq: number, text: string, turnId: number | null = TURN): AgentEvent {
  return {
    seq,
    turnId,
    timestampMs: 1727000000000,
    kind: 'messageDelta',
    parentToolUseId: null,
    delta: { kind: 'text', text },
  };
}

/** 子代理归因键的 delta（每配对键独立簿记断言的 fixture 半边）。 */
function keyedTextDelta(seq: number, parentToolUseId: string, text: string): AgentEvent {
  return {
    seq,
    turnId: TURN,
    timestampMs: 1727000000000,
    kind: 'messageDelta',
    parentToolUseId,
    delta: { kind: 'text', text },
  };
}

/** thinking 增量（推理流半边；跨轮再流式回归的 fixture）。 */
function thinkingDelta(seq: number, thinking: string, turnId: number | null = TURN): AgentEvent {
  return {
    seq,
    turnId,
    timestampMs: 1727000000000,
    kind: 'messageDelta',
    parentToolUseId: null,
    delta: { kind: 'thinking', thinking },
  };
}

/** 密封 assistant 消息（携工具调用）：sdk loop 轮末收口事件形态。 */
function toolUseEvent(seq: number): AgentEvent {
  return {
    seq,
    turnId: TURN,
    timestampMs: 1727000000000,
    kind: 'message',
    role: 'assistant',
    blocks: [{ kind: 'toolUse', id: 'tu_1', name: 'Bash', input: { command: 'ls' } }],
    parentToolUseId: null,
  };
}

/** 密封 tool 结果消息（工具执行回灌的事件形态）。 */
function toolResultEvent(seq: number): AgentEvent {
  return {
    seq,
    turnId: TURN,
    timestampMs: 1727000000000,
    kind: 'message',
    role: 'tool',
    blocks: [{ kind: 'toolResult', id: 'tu_1', content: '目录内容', isError: false }],
    parentToolUseId: null,
  };
}

/** 密封 assistant 消息（携两枚工具调用）：逐条结果事件就地补全的 fixture。 */
function twoToolUseEvent(seq: number): AgentEvent {
  return {
    seq,
    turnId: TURN,
    timestampMs: 1727000000000,
    kind: 'message',
    role: 'assistant',
    blocks: [
      { kind: 'toolUse', id: 'tu_1', name: 'Bash', input: { command: 'ls' } },
      { kind: 'toolUse', id: 'tu_2', name: 'Read', input: { path: 'a.ts' } },
    ],
    parentToolUseId: null,
  };
}

/** 指定 id 的密封 tool 结果消息（多工具调用逐条回灌的 fixture）。 */
function toolResultOf(seq: number, id: string, content: string): AgentEvent {
  return {
    seq,
    turnId: TURN,
    timestampMs: 1727000000000,
    kind: 'message',
    role: 'tool',
    blocks: [{ kind: 'toolResult', id, content, isError: false }],
    parentToolUseId: null,
  };
}

function recordRow(turnId: number, status: TurnSummary['status']): TurnSummary {
  return {
    turnId,
    sessionId: status === 'running' ? 's-live' : 's-done',
    status,
    startedAt: 1727000000000,
    finishedAt: status === 'running' ? null : 1727000001000,
    numTurns: null,
    costUsd: null,
    durationMs: null,
    error: null,
  };
}

const SESSION_BODY = {
  root: ROOT,
  prompt: '帮我跑一轮 loop',
  permissionMode: 'bypassPermissions' as const,
  sessionId: 'ses-0-1727000000000',
  source: 'explore',
  sourceRef: null,
  // 执行根尾位（null = 回落 root；会话参数 8 键的既有形态）
  cwd: null,
};

/** Channel mock 实例形状（vi.hoisted 内 class 不外泄类型，取其结构）。 */
interface ChannelLike {
  onmessage: (message: unknown) => void;
  /** 生产同构投递口（读私有字段，不经 `get`） */
  deliver: (message: unknown) => void;
}

function lastChannel(): ChannelLike {
  const instance = ChannelMock.instances.at(-1);
  if (!instance) throw new Error('sendMessages 未创建 Channel');
  return instance;
}

/** `Record` 收口的 finish chunk（该轮消息已由事件建立时只有这一条） */
function finishChunk(row: TurnSummary, seq: number | null): AgentUIMessageChunk {
  return { type: 'finish', messageMetadata: { seq, parentToolUseId: null, record: row } };
}

/** 空传输：把已 drain 的 chunk 序列一次性回放给真实 reducer（帧序的归约侧判据） */
function replayTransport(chunks: AgentUIMessageChunk[]): ChatTransport<AgentUIMessage> {
  return {
    sendMessages: async () =>
      new ReadableStream<AgentUIMessageChunk>({
        start(controller) {
          for (const chunk of chunks) controller.enqueue(chunk);
          controller.close();
        },
      }),
    reconnectToStream: async () => null,
  };
}

/** 已 drain 的 chunk 序列经真实 `useChat` reducer 归约后的消息（本地提问除外） */
async function reducedBy(chunks: AgentUIMessageChunk[]): Promise<AgentUIMessage[]> {
  const rendered = renderHook(() =>
    useChat<AgentUIMessage>({ transport: replayTransport(chunks) }),
  );
  await act(async () => {
    await rendered.result.current.sendMessage({
      id: 'local-q',
      parts: [{ type: 'text', text: '驱动发送' }],
    });
  });
  await waitFor(() => expect(rendered.result.current.status).toBe('ready'));
  return rendered.result.current.messages.filter((message) => message.id !== 'local-q');
}

/** 从 transport 读流并收集全部 chunk（流 error 则 promise reject）。 */
async function drain(stream: ReadableStream<AgentUIMessageChunk>): Promise<AgentUIMessageChunk[]> {
  const reader = stream.getReader();
  const collected: AgentUIMessageChunk[] = [];
  for (;;) {
    const next = await reader.read();
    if (next.done) break;
    collected.push(next.value);
  }
  return collected;
}

function send(transport: TauriAgentTransport, body: object = SESSION_BODY) {
  return transport.sendMessages({
    trigger: 'submit-message',
    chatId: 'chat-1',
    messageId: undefined,
    messages: [],
    abortSignal: undefined,
    body,
  });
}

function startCallArgs(): Record<string, unknown> {
  const call = invokeMock.mock.calls.filter(([name]) => name === 'agent_start').at(-1);
  if (!call) throw new Error('agent_start 未被调用');
  return call[1] as Record<string, unknown>;
}

