describe('useChangeFlowRun：invoke reject（异常面）', () => {
  it('start reject → error 呈现可重试：重试成功后 error 复位、订阅照常建立（Channel 复用不叠加）', async () => {
    const { result } = await mounted();

    startResult = '同 change 已有并行 run';
    await act(async () => {
