  it('降级哨兵的 meta 可回读（运行期 zod 单实例 + 4.x `.meta()` 面）', () => {
    const sentinel = (argsSchemas.agentStart as ZodObject).shape.onEvent;
    expect(sentinel).toBeInstanceOf(ZodType);
    expect((sentinel as ZodType).meta()).toMatchObject({
